# -*- coding: utf-8 -*-
"""
Object that allows you to run keywords simultaneously, while maintaining robot logs

:copyright: Nokia Networks
:author: MN_RAN_PZ_KRK_TAG
:contact: I_MN_RAN_PZ_KRK_TAG@internal.nsn.com
:maintainer: I_MN_RAN_PZ_KRK_TAG@internal.nsn.com
"""
import threading
import traceback
from functools import partial
from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn
from robot.output.output import Output
from robot.output.loggerhelper import Message
from signal import setitimer, ITIMER_REAL
from robot.running.timeouts.posix import Timeout
from taf.rfrl.utilities.robot.RobotWrapper import _disable_cached_logs


class RobotThreads:
    threads_messages = {}
    _old_signal_handle_function = None

    def __init__(self):
        """
        :author: jakub.siluch@nokia.com
        :maintainer: jakub.siluch@nokia.com
        :note: Please contact with maintainer with any issue of this KW(prototype version)
        Example of execution, collect bts_sw_version simultaneously on bts with id 0 and 1:
            from taf.rfrl.bts.devices.du.du_operations import GnbDuOperations
            bbu = GnbDuOperations()
            with RobotThreads() as threads:
                threads.create_thread(thread_name="Thread_TEST", function=bbu.get_bts_sw_version, bts_id=1, du_id=0)
                main_thread_return = bbu.get_bts_sw_version(bts_id=0, du_id=0)
                threads.thread_results["Thread_MAIN"] = main_thread_return
                return threads.thread_results
        In this example logs from both(!) KW execution is stored in log.html
        """
        self.threads = []
        self.thread_results = {}
        self.thread_exceptions = {}
        self._fix_signal_handle_in_thread()
        _disable_cached_logs()
        self.hacked_start_keyword = Output.start_keyword
        self.hacked_end_keyword = Output.end_keyword
        self.hacked_message = Output.message
        self.hacked_write = logger.librarylogger.write
        self.start_capturing_messages()

    def return_from_thread(self, thread_name, func, raise_exception=True, *args, **kwargs):
        # TODO - add failing KW when exception is raised
        try:
            return_from_func = func(*args, **kwargs)
            self.thread_results[thread_name] = return_from_func
        except Exception as e:
            self.thread_exceptions[thread_name] = e
            if raise_exception:
                raise e

    def _fix_signal_handle_in_thread(self):
        """
        Fix error from python 3.9: "signal only works in main thread of the main interpreter"
        """
        if RobotThreads._old_signal_handle_function:
            return
        old_func = Timeout._start_timer
        RobotThreads._old_signal_handle_function = old_func

        def new_start_timer(timeout_obj):
            if threading.currentThread().getName() in [thread.name for thread in self.threads]:
                setitimer(ITIMER_REAL, getattr(timeout_obj, "_timeout"))
            else:
                old_func(timeout_obj)

        Timeout._start_timer = new_start_timer
        return old_func

    @staticmethod
    def _revert_signal_handle_in_thread():
        if not RobotThreads._old_signal_handle_function:
            return
        Timeout._start_timer = RobotThreads._old_signal_handle_function
        RobotThreads._old_signal_handle_function = None

    def create_thread(self, thread_name, function, daemon=True, raise_exception=True, *args, **kwargs):
        func = partial(self.return_from_thread, thread_name, function, raise_exception, *args, **kwargs)
        thread = threading.Thread(name=thread_name, target=func, daemon=daemon)
        self.threads_messages[thread_name] = []
        self.threads.append(thread)
        thread.start()

    def wait_until_all_threads_finished(self):
        try:
            while True in [t.isAlive() for t in self.threads]:
                [t.join(2) for t in self.threads if t is not None and t.isAlive()]
        except AttributeError:  # Python 3.9 adjustment
            while True in [t.is_alive() for t in self.threads]:
                [t.join(2) for t in self.threads if t is not None and t.is_alive()]

    def raise_exception_if_any_thread_failed(self, full_traceback=False):
        exception_messages = []
        for thread_name, exception in self.thread_exceptions.items():
            if full_traceback:
                exception_string = ''.join(traceback.format_exception(
                    type(exception), exception, exception.__traceback__))
            else:
                exception_string = str(exception)
            exception_message = f"Exception from {thread_name}:\nTYPE:{type(exception)}\n{exception_string}"
            exception_messages.append(exception_message)
        if self.thread_exceptions:
            raise RobotThreadsException("Some threads failed\n" + "\n".join(exception_messages))

    def __enter__(self):
        self._fix_signal_handle_in_thread()
        self.start_capturing_messages()
        return self

    def __exit__(self, ex_type, value, traceback):
        if str(value) == "Execution terminated by signal":
            self.stop_capturing_messages()
            return
        self.wait_until_all_threads_finished()
        self.stop_capturing_messages()
        self._revert_signal_handle_in_thread()
        for thread_name in [thread.name for thread in self.threads]:
            self.write_captured_messages(thread_name=thread_name)

    def start_capturing_messages(self):
        self.capture_start_keyword()
        self.capture_message()
        self.capture_thread_messages()
        self.capture_end_keyword()

    def stop_capturing_messages(self):
        Output.start_keyword = self.hacked_start_keyword
        Output.message = self.hacked_message
        logger.librarylogger.write = self.hacked_write
        Output.end_keyword = self.hacked_end_keyword

    def write_captured_messages(self, thread_name):
        output = BuiltIn()._context.output
        started_keywords = []
        for captured_message in self.threads_messages[thread_name]:
            if "Message" in str(type(captured_message)):
                output.message(captured_message)
            else:
                try:
                    mess_id = id(captured_message.data)
                except AttributeError:
                    mess_id = id(captured_message)
                if mess_id in started_keywords:
                    output.end_keyword(captured_message)
                else:
                    started_keywords.append(mess_id)
                    output.start_keyword(captured_message)

    def capture_thread_messages(self):

        def new_write(msg, level, html=False):
            self.hacked_write(msg, level, html)
            thread_name = threading.currentThread().getName()
            if thread_name in list(self.threads_messages):
                if level == "WARN":
                    mod_msg = "WARN FROM {}, WILL BE REPEATED AT THE END OF THREAD: \n ".format(thread_name) + msg
                    logger.librarylogger.console(mod_msg)
                self.threads_messages[thread_name].append(Message(msg, level, html))

        logger.librarylogger.write = new_write

    def capture_start_keyword(self):

        def new_start_keyword(output, kw):
            thread_name = threading.currentThread().getName()
            if thread_name in list(self.threads_messages):
                self.threads_messages[thread_name].append(kw)
            else:
                self.hacked_start_keyword(output, kw)

        Output.start_keyword = new_start_keyword

    def capture_end_keyword(self):

        def new_end_keyword(output, kw):
            thread_name = threading.currentThread().getName()
            if thread_name in list(self.threads_messages):
                self.threads_messages[thread_name].append(kw)
            else:
                self.hacked_end_keyword(output, kw)

        Output.end_keyword = new_end_keyword

    def capture_message(self):

        def new_message(output, message):
            thread_name = threading.currentThread().getName()
            if thread_name in list(self.threads_messages):
                self.threads_messages[thread_name].append(message)
            else:
                self.hacked_message(output, message)

        Output.message = new_message


class RobotThreadsException(Exception):
    pass
